from pathlib import Path
import re
p=Path('caso001-rev01/index.html')
s=p.read_text()
if 'P2.12D.8 · DIRECTOR + BITÁCORA' in s:
    raise SystemExit('D8 already applied')

css=r'''
/* P2.12D.8 · DIRECTOR + BITÁCORA */
.directorPanel,.logPanel{padding:0;overflow:hidden;border-color:#59432e}.sectionDossierHead{display:flex;justify-content:space-between;gap:12px;align-items:center;padding:12px 14px;border-bottom:1px solid #4d3927;background:linear-gradient(180deg,#18130f,#0f0d0b)}.sectionDossierHead small{font-size:7px;letter-spacing:.16em;color:#8f7c66;font-weight:900}.sectionDossierHead b{display:block;margin-top:3px;font:700 18px/1.1 Georgia,serif;color:#eadcc9}.sectionDossierHead .miniStamp{border:2px solid rgba(145,43,39,.48);color:#c65b52;padding:4px 6px;transform:rotate(-4deg);font-size:7px;letter-spacing:.1em;font-weight:950}.directorBody{padding:13px 14px 15px}.directorIntro{border-left:3px solid #8a6a3d;background:#15110d;padding:10px 11px;color:#bbaa95;font-size:10px;line-height:1.5;margin-bottom:10px}.directorControls{display:grid;gap:8px}.directorPrimary{width:100%;text-align:left;display:flex;align-items:center;justify-content:space-between;gap:8px;border-color:#80613a!important;background:linear-gradient(180deg,#241b11,#17120d)!important;color:#e6c587!important}.directorPrimary span{font-size:8px;letter-spacing:.1em;color:#998166}.hostControls{margin-top:10px;padding-top:10px;border-top:1px solid #403124}.hostControlsLabel{font-size:7px;letter-spacing:.13em;color:#766a5c;margin-bottom:7px;font-weight:900}.hostControlGrid{display:grid;grid-template-columns:1fr 1fr;gap:6px}.hostControlGrid .btn{padding:9px 10px;font-size:9px}.logBody{padding:4px 14px 14px}.caseLog{display:grid;gap:0;max-height:560px;overflow:auto;padding:4px 0}.logEntry{position:relative;display:grid;grid-template-columns:42px 1fr;gap:10px;padding:11px 0;border-bottom:1px solid #2f261e}.logEntry:last-child{border-bottom:0}.logMarker{width:34px;height:34px;border:1px solid #5e4934;background:#100e0b;display:grid;place-items:center;color:#c7a36c;font-size:13px;position:relative}.logMarker:after{content:"";position:absolute;top:34px;bottom:-18px;left:16px;width:1px;background:#3d3024}.logEntry:last-child .logMarker:after{display:none}.logCopy{min-width:0}.logTop{display:flex;justify-content:space-between;gap:8px;align-items:flex-start}.logTop b{font-size:9px;letter-spacing:.09em;color:#dfc190}.logTime{font:700 7px/1 ui-monospace,monospace;color:#756958;white-space:nowrap}.logText{margin-top:5px;color:#c7b9a8;font-size:11px;line-height:1.48}.logEntry.directorDispatch{margin:8px 0;border:1px solid #725733;background:linear-gradient(135deg,#d0ba94,#ae916c);color:#251c14;padding:11px 10px}.logEntry.directorDispatch .logMarker{background:#6d271f;color:#f1d7b2;border-color:#7c332c}.logEntry.directorDispatch .logMarker:after{display:none}.logEntry.directorDispatch .logTop b{color:#70261f}.logEntry.directorDispatch .logTime{color:#65503a}.logEntry.directorDispatch .logText{color:#35291f;font-family:Georgia,serif;font-size:12px}.logEntry.accusation .logMarker{border-color:#823d38;color:#e49e91}.logEntry.solutionLog .logMarker{border-color:#3f654a;color:#9bd0aa}.logEntry.stageLog .logMarker{color:#ddba6b}.logEmpty{padding:16px 0;color:#897a69;font-size:10px;font-style:italic}.logSeal{font-size:7px;letter-spacing:.11em;color:#6f6152;padding:8px 0 0;text-align:right}.directorLatest{margin-top:10px;border:1px solid #675035;background:#12100d;padding:10px}.directorLatest small{display:block;font-size:7px;letter-spacing:.12em;color:#8f795e;margin-bottom:5px}.directorLatest b{display:block;font-family:Georgia,serif;color:#dec59e;margin-bottom:4px}.directorLatest p{margin:0;color:#baaa96;font-size:10px;line-height:1.45}
@media(max-width:620px){.hostControlGrid{grid-template-columns:1fr}.logEntry{grid-template-columns:36px 1fr}.logMarker{width:30px;height:30px}.logMarker:after{left:14px;top:30px}.logTop{display:grid;gap:3px}}
'''
anchor='/* P2.12D.7 · PRIVATE CHARACTER DOSSIER */'
if anchor not in s: raise SystemExit('D7 marker missing')
s=s.replace(anchor,css+'\n'+anchor,1)

old='''      <section class="panel"><h2 style="margin-top:0">Controles</h2><div id="controls" class="toolbar"></div></section>
      <section class="panel"><h2 style="margin-top:0">Bitácora</h2><div id="timeline" class="timeline"></div></section>'''
new='''      <section class="panel directorPanel"><div class="sectionDossierHead"><div><small>COMUNICACIONES · ASISTENCIA</small><b>Director del caso</b></div><span class="miniStamp">CANAL ABIERTO</span></div><div class="directorBody"><div class="directorIntro">Podés pedir una orientación cuando el equipo necesite destrabar la investigación. El Director no reemplaza la deducción: señala una línea para volver a revisar.</div><div id="controls" class="directorControls"></div><div id="directorLatest"></div></div></section>
      <section class="panel logPanel"><div class="sectionDossierHead"><div><small>REGISTRO COMPARTIDO</small><b>Bitácora del expediente</b></div><span class="miniStamp">EN CURSO</span></div><div class="logBody"><div id="timeline" class="timeline caseLog"></div><div class="logSeal">EXPEDIENTES · CASO 001 · REGISTRO PÚBLICO</div></div></section>'''
if old not in s: raise SystemExit('controls/log html anchor missing')
s=s.replace(old,new,1)

helpers=r'''function eventClock(value){const d=new Date(value||'');if(Number.isNaN(d.getTime()))return '—';return d.toLocaleTimeString('es-AR',{hour:'2-digit',minute:'2-digit'})}
function logEntry(ev){const p=ev?.payload||{},time=eventClock(ev?.created_at);if(ev?.event_type==='director')return `<article class="logEntry directorDispatch"><div class="logMarker">✦</div><div class="logCopy"><div class="logTop"><b>${esc(p.title||'MENSAJE DEL DIRECTOR')}</b><span class="logTime">${esc(time)}</span></div><div class="logText">${esc(p.body||'')}</div></div></article>`;if(ev?.event_type==='stage_changed')return `<article class="logEntry stageLog"><div class="logMarker">${esc(p.stage||'•')}</div><div class="logCopy"><div class="logTop"><b>NUEVA ETAPA LIBERADA</b><span class="logTime">${esc(time)}</span></div><div class="logText">El expediente avanzó a la Etapa ${esc(p.stage||'—')}.</div></div></article>`;if(ev?.event_type==='accusation_locked')return `<article class="logEntry accusation"><div class="logMarker">!</div><div class="logCopy"><div class="logTop"><b>ACUSACIÓN BLOQUEADA</b><span class="logTime">${esc(time)}</span></div><div class="logText">${esc(p.suspect_name||'—')} · ${esc(p.location_name||'—')} · ${esc(p.object_name||'—')}${p.motive_text?`<br>Hipótesis: ${esc(p.motive_text)}`:''}</div></div></article>`;if(ev?.event_type==='solution')return `<article class="logEntry solutionLog"><div class="logMarker">✓</div><div class="logCopy"><div class="logTop"><b>EXPEDIENTE CERRADO</b><span class="logTime">${esc(time)}</span></div><div class="logText">Se liberó la reconstrucción final del caso.</div></div></article>`;return `<article class="logEntry"><div class="logMarker">●</div><div class="logCopy"><div class="logTop"><b>PARTIDA INICIADA</b><span class="logTime">${esc(time)}</span></div><div class="logText">La investigación quedó oficialmente abierta.</div></div></article>`}
'''
pat=re.compile(r'function renderTimeline\(\)\{.*?\}\nfunction latestEvent\(type\)\{',re.S)
m=pat.search(s)
if not m: raise SystemExit('renderTimeline anchor missing')
new_timeline=r'''function renderTimeline(){const events=(view?.events||[]).filter(e=>['game_started','stage_changed','director','accusation_locked','solution'].includes(e.event_type)).sort((a,b)=>new Date(a.created_at)-new Date(b.created_at));$('#timeline').innerHTML=events.length?events.map(logEntry).join(''):'<div class="logEmpty">La bitácora se completará a medida que avance la investigación.</div>';const lastDirector=[...events].reverse().find(e=>e.event_type==='director'),box=$('#directorLatest');if(box)box.innerHTML=lastDirector?`<div class="directorLatest"><small>ÚLTIMA ORIENTACIÓN RECIBIDA · ${esc(eventClock(lastDirector.created_at))}</small><b>${esc(lastDirector.payload?.title||'Director')}</b><p>${esc(lastDirector.payload?.body||'')}</p></div>`:''}
'''
s=s[:m.start()]+helpers+new_timeline+'function latestEvent(type){'+s[m.end():]

pat2=re.compile(r'function renderControls\(\)\{.*?\}\nfunction renderGame\(\)\{',re.S)
m2=pat2.search(s)
if not m2: raise SystemExit('renderControls anchor missing')
new_controls=r'''function renderControls(){const room=view?.room||{},state=view?.public_state||{};let html='';if(room.status==='active')html+=`<button class="btn directorPrimary" id="directorHelp"><span>PEDIR ORIENTACIÓN AL DIRECTOR</span><span>CANAL →</span></button>`;if(view?.is_host&&room.status==='active'){let host='';if(Number(state.stage||1)<3&&!state.accusation_locked)host+='<button class="btn" id="advanceStage">ADELANTAR ETAPA</button>';host+=`<button class="btn" id="pause">${state.paused?'REANUDAR':'PAUSAR'}</button><button class="btn" id="addTime">+2 MIN</button>`;html+=`<div class="hostControls"><div class="hostControlsLabel">CONTROLES DEL ANFITRIÓN</div><div class="hostControlGrid">${host}</div></div>`}$('#controls').innerHTML=html||'<span class="muted">El canal del Director estará disponible durante la partida.</span>';$('#directorHelp')?.addEventListener('click',()=>doAction(async()=>{await adapter.action('director_help');await refresh(true)},'El Director dejó una orientación.'));$('#advanceStage')?.addEventListener('click',()=>doAction(async()=>{await adapter.action('advance_stage');await refresh(true)},'Nueva etapa liberada.'));$('#pause')?.addEventListener('click',()=>doAction(async()=>{await adapter.action('pause_toggle');await refresh(true)},state.paused?'Cronómetro reanudado.':'Cronómetro pausado.'));$('#addTime')?.addEventListener('click',()=>doAction(async()=>{await adapter.action('add_time',{seconds:120});await refresh(true)},'Se agregaron 2 minutos.'))}
'''
s=s[:m2.start()]+new_controls+'function renderGame(){'+s[m2.end():]

p.write_text(s)
print('P2.12D.8 patch complete')
